import{_ as e,o as r,c as d,ag as o}from"./chunks/framework.DNmTgtHf.js";const p=JSON.parse('{"title":"Part 12 — API Design","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_12_API_Design.md","filePath":"todo/study_plan/parts/Part_12_API_Design.md"}'),s={name:"todo/study_plan/parts/Part_12_API_Design.md"};function i(a,t,n,c,l,h){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="part-12-—-api-design" tabindex="-1">Part 12 — API Design <a class="header-anchor" href="#part-12-—-api-design" aria-label="Permalink to &quot;Part 12 — API Design&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 6 (shared). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_12-api-design-—-topic-inventory" tabindex="-1">12 API Design — topic inventory <a class="header-anchor" href="#_12-api-design-—-topic-inventory" aria-label="Permalink to &quot;12 API Design — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>RESTful resource modeling</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>2</td><td>Versioning — URI, header, content negotiation</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Pagination — offset, cursor, keyset</td><td>🔴 💼 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: implement keyset pagination — <code>WHERE id &gt; :lastSeenId ORDER BY id LIMIT 20</code> + response includes <code>nextCursor</code> (30 min)</td></tr><tr><td>4</td><td>Filtering, sorting, projections</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>Idempotency — Idempotency-Key header, design</td><td>🔴 💼 🎯</td><td>D</td><td>2 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: middleware that reads <code>Idempotency-Key</code> header + stores <code>(key, response)</code> in Redis with 24h TTL + serves cached response on retry (20 min)</td></tr><tr><td>6</td><td>Error response design (RFC 7807 Problem Details)</td><td>🔴 💼 🎯</td><td>MP</td><td>1 hr 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: @RestControllerAdvice mapping a DomainException to ProblemDetail with type/title/status/detail/instance fields (15 min)</td></tr><tr><td>7</td><td>Authentication header design</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Bulk operations</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Async / long-running APIs (202 + status endpoint — your KYC pattern)</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>HATEOAS — what it is, why most APIs skip it</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>OpenAPI spec &amp; code-gen</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>API deprecation strategy</td><td>🟡</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~13.5 hrs</td><td>~1.25 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~17.75 hrs</td><td>~1.6 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~18.75 hrs</td><td>~1.7 wk</td><td></td></tr></tbody></table><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Cursor vs offset pagination — when does each fit? <ul><li><strong>Why asked:</strong> Senior REST canonical. Offset: <code>?page=5&amp;size=20</code> — simple, supports random page jumps. Breaks under writes (page N may have repeats / skips if rows added/removed). Cursor / keyset: <code>?after=&lt;opaque&gt;</code> — stable across writes, only forward/backward, no random jumps. Use keyset for infinite-scroll feeds, offset for paginated tables where users jump pages.</li></ul></li><li><strong>Q:</strong> Walk through your idempotency design for POST /verifications. <ul><li><strong>Why asked:</strong> KYC-canonical. Client generates <code>Idempotency-Key</code> UUID. Server stores <code>(key, request_hash, response, expires_at)</code> in Redis with 24h TTL. On retry: same key + same hash → return cached response. Same key + different hash → 412 Precondition Failed. Different key → process new request.</li></ul></li><li><strong>Q:</strong> RFC 7807 Problem Details — what fields, why use it? <ul><li><strong>Why asked:</strong> Modern error response standard. Fields: <code>type</code> (URI identifying error type), <code>title</code> (human-readable summary), <code>status</code> (HTTP status), <code>detail</code> (instance-specific message), <code>instance</code> (URI of the specific error occurrence). Use it: machine-readable + human-readable + standardized.</li></ul></li><li><strong>Q:</strong> REST versioning — pick a strategy, defend it. <ul><li><strong>Why asked:</strong> Architecture decision. URI versioning (<code>/v1/users</code>): visible, easy to route, easy to deprecate. Header versioning (<code>Accept: application/vnd.app.v1+json</code>): &quot;pure&quot; REST, lets URI stay stable, harder to debug. Most APIs pick URI versioning for simplicity. Defend per your stack: KYC SDK probably prefers URI versioning (easier for partner banks).</li></ul></li><li><strong>Q:</strong> Design an async long-running API for KYC verification. <ul><li><strong>Why asked:</strong> Your platform pattern. Client POST /verifications → 202 Accepted + Location: /verifications/{id} + status URL. Polling: GET /verifications/{id}/status. Statuses: PENDING / IN_PROGRESS / VERIFIED / REVIEW / ERROR / FAILED. Webhook on completion as alternative to polling.</li></ul></li><li><strong>Q:</strong> Bulk operations — POST /users with array vs N parallel POST /users — what are the trade-offs? <ul><li><strong>Why asked:</strong> Practical design. Bulk: fewer round-trips, atomic if all-or-nothing, harder to retry partial failures, request size limits. N parallel: clean per-request error handling, retryable per item, but N times the HTTP overhead. Common pattern: bulk endpoint that returns per-item status (some succeeded, some failed).</li></ul></li><li><strong>Q:</strong> Filtering + projections — design <code>GET /transactions?status=COMPLETED&amp;fields=id,amount</code>. <ul><li><strong>Why asked:</strong> Practical query design. Filtering: <code>?status=...</code> for equality, <code>?amount[gt]=100</code> for ranges, or full GraphQL-style. Projections: <code>?fields=id,amount</code> selects only those fields. Sparse fieldsets reduce bandwidth. Document precedence: filter → sort → paginate → project.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your idempotency cache is in Redis with TTL=24h. What happens if Redis fails between two retries? <ul><li><strong>Gotcha:</strong> Without idempotency cache, retry processes again → duplicate effect. Mitigations: (1) write idempotency key to DB transactionally with the operation, (2) check DB for prior key on retry, (3) fallback to &quot;best effort dedup&quot; with shorter window using DB.</li></ul></li><li><strong>Q:</strong> You return 500 with no body. Why is this hostile to clients? <ul><li><strong>Gotcha:</strong> Clients can&#39;t distinguish transient (retry-safe) from permanent (don&#39;t retry) failures, and can&#39;t show useful error messages. Always return RFC 7807 Problem Details with type, title, status, detail. Include correlationId for support requests.</li></ul></li><li><strong>Q:</strong> Why is offset pagination broken for &quot;concurrently-modified&quot; data sets? <ul><li><strong>Gotcha:</strong> If rows are added/removed between page fetches, you get duplicates or missing rows. E.g., page=1&amp;size=10 returns rows 1-10; new row inserted at start; page=2&amp;size=10 now starts from the OLD row 11, which is now row 12 — you missed the new row 10. Keyset pagination uses stable cursor (last-seen ID), immune to insertions.</li></ul></li><li><strong>Q:</strong> Why is HATEOAS rarely implemented in practice? <ul><li><strong>Gotcha:</strong> Promise: client discovers state transitions via links → loose coupling. Reality: clients still hardcode endpoint shapes; the discovery layer doesn&#39;t save real work; mobile SDKs especially can&#39;t dynamically follow links efficiently. Most APIs document their endpoints out-of-band (OpenAPI) and skip HATEOAS entirely.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Idempotency-Key end-to-end design</strong> (~2.5 hrs row 5) — directly your KYC platform. Storage choices (Redis vs DB), TTL, request-hash matching, conflict handling.</li><li><strong>Async long-running API for KYC</strong> (~2 hrs row 9) — your platform&#39;s exact pattern. 202 + status URL + webhook. Walk it through end-to-end.</li><li><strong>Pagination cursor design</strong> (~2 hrs row 3) — cursor-based pagination for an unbounded list (e.g., transaction history). Encoding the cursor opaquely (Base64 of <code>(timestamp, id)</code>), security considerations.</li><li><strong>API versioning + deprecation strategy</strong> (~2 hrs combined rows 2 + 12) — pick strategy, document migration path for partner banks. Sunset header standards.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up API design exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Idempotency-Key middleware</strong> (~60 min) — Spring filter that intercepts POST with Idempotency-Key header. Stores <code>(key, request_hash, response)</code> in Redis with 24h TTL. On retry: matched key + hash → replay cached response. Mismatched hash → 412. Add unit tests covering all paths.</li><li><strong>RFC 7807 Problem Details across error types</strong> (~45 min) — define a domain exception hierarchy (ValidationError, NotFoundError, ConflictError). Map each to ProblemDetail with <code>type</code> URIs pointing to your documentation. Add <code>correlationId</code> for support traceability.</li><li><strong>Cursor pagination implementation</strong> (~45 min) — endpoint <code>GET /events?cursor=&lt;base64&gt;&amp;limit=20</code>. Cursor encodes <code>(timestamp, id)</code>. Validate cursor monotonicity. Return <code>nextCursor</code> in response. Test with concurrent inserts to verify stability.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Design + implement an async long-running API</strong> (~90 min) — POST /verifications returns 202 + Location. GET /verifications/{id}/status returns current state. Webhook delivery on completion. Idempotent retries via Idempotency-Key. Full happy + error paths.</li><li><strong>API versioning migration walkthrough</strong> (~60 min) — document migration from v1 → v2 for a partner SDK. Include: backward-compatible additive changes, breaking changes via new versions, deprecation headers, sunset timeline, communication plan to partners.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5 hrs</strong></td><td><strong>~0.45 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~65 min for Part 12 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Offset vs cursor pagination — when each fits?</strong> A. Offset: supports random page jumps, breaks under concurrent writes. Cursor: stable under writes, only forward-only navigation. Use cursor for feeds, offset for static result sets.</p><p><strong>Q. Idempotency-Key three rules.</strong> A. (1) Client generates, server caches. (2) Match cached response on same key + same request hash. (3) Different hash with same key = 412 (client error).</p><p><strong>Q. RFC 7807 fields?</strong> A. type (URI), title (human summary), status (HTTP code), detail (specific message), instance (URI of error occurrence). Plus extensions for traceability.</p><p><strong>Q. Async / long-running API pattern?</strong> A. POST returns 202 + Location: /resource/{id}. GET /resource/{id}/status returns current state. Optional webhook for completion notification.</p><p><strong>Q. Which HTTP status codes for what?</strong> A. 200 OK, 201 Created (with Location), 202 Accepted (async), 204 No Content, 400 Bad Request (client validation), 401 Unauthorized (no auth), 403 Forbidden (auth but no perm), 404 Not Found, 409 Conflict (e.g., duplicate), 412 Precondition Failed (idempotency-key mismatch), 422 Unprocessable Entity (semantic validation), 429 Too Many Requests (rate limit), 500 Server Error, 503 Service Unavailable.</p><p><strong>Q. Why is HATEOAS usually skipped?</strong> A. Real clients hardcode endpoint shapes anyway. The discovery layer adds complexity without removing the need for out-of-band API documentation (OpenAPI).</p>',28)])])}const m=e(s,[["render",i]]);export{p as __pageData,m as default};
